mapper.select:
select t.user_id as userId, t.registration_id as registrationId, t.platform as platform,
       t.create_time as createTime, t.update_time as updateTime
from user_alias t
where 1=1 and t.status_cd= #{statusCd}

    and t.user_id = #{userId}


    and t.registration_id = #{registrationId}


    and t.platform = #{platform}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update user_alias t set t.status_cd = #{statusCd}

    ,t.user_id = #{userId}


    , t.registration_id= #{registrationId}


    , t.platform= #{platform}

where 1=1

    and t.user_id = #{userId}


    and t.registration_id = #{registrationId}


    and t.platform = #{platform}

mapper.select:
